 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    # The full line of 2s identifies the movement axis and direction.
    line_row = next((r for r in range(h) if all(g[r][c] == 2 for c in range(w))), None)
    line_col = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    obj = [(r, c, g[r][c]) for r in range(h) for c in range(w)
           if g[r][c] not in (background, 2)]
    if not obj:
        return g
    if line_col is not None:
        cols = [c for r, c, v in obj]
        if min(cols) > line_col:
            delta = line_col + 1 - min(cols)
            far = max(c for r, c, v in obj) + delta
            stripe = far + 1
        else:
            delta = line_col - 1 - max(cols)
            far = min(c for r, c, v in obj) + delta
            stripe = far - 1
        for r, c, v in obj:
            g[r][c] = background
        for r, c, v in obj:
            g[r][c + delta] = v
        if 0 <= stripe < w:
            for r in range(h):
                g[r][stripe] = 8
    elif line_row is not None:
        rows = [r for r, c, v in obj]
        if min(rows) > line_row:
            delta = line_row + 1 - min(rows)
            far = max(r for r, c, v in obj) + delta
            stripe = far + 1
        else:
            delta = line_row - 1 - max(rows)
            far = min(r for r, c, v in obj) + delta
            stripe = far - 1
        for r, c, v in obj:
            g[r][c] = background
        for r, c, v in obj:
            g[r + delta][c] = v
        if 0 <= stripe < h:
            g[stripe] = [8] * w
    return g
